1099	func collectChangedFiles(ctx context.Context, repo *git.Repository) (changedFilesResult, error) {
1100		// Get worktree root directory for running git command
1101		wt, err := repo.Worktree()
1102		if err != nil {
1103			return changedFilesResult{}, fmt.Errorf("failed to get worktree: %w", err)
1104		}
1105		repoRoot := wt.Filesystem.Root()
1106	
1107		// Use -z for NUL-separated output (handles quoted filenames with spaces/special chars)
1108		// Use -uall to list individual untracked files instead of collapsed directories.
1109		// Note: CLAUDE.md warns against -uall for user-facing display, but we need the full list
1110		// for checkpointing.
1111		cmd := exec.CommandContext(ctx, "git", "status", "--porcelain", "-z", "-uall")
1112		cmd.Dir = repoRoot
1113		output, err := cmd.Output()
1114		if err != nil {
1115			return changedFilesResult{}, fmt.Errorf("failed to get git status in %s: %w", repoRoot, err)
1116		}
1117	
1118		changedSeen := make(map[string]struct{})
1119		deletedSeen := make(map[string]struct{})
1120	
1121		// Parse NUL-separated output
1122		// Format: XY filename\0 (for most entries)
1123		// For renames/copies: XY newname\0oldname\0
1124		entries := strings.Split(string(output), "\x00")
1125	
1126		for i := 0; i < len(entries); i++ {
1127			entry := entries[i]
1128			if len(entry) < 3 {
1129				continue
1130			}
1131	
1132			// git status --porcelain format: XY filename
1133			// X = staging status, Y = worktree status
1134			staging := entry[0]
1135			wtStatus := entry[1]
1136			filename := entry[3:] // No TrimSpace needed with -z format
1137	
1138			// Handle R/C (rename/copy) first - they have a second entry we must skip
1139			// even if the new filename is an infrastructure path
1140			if staging == 'R' || staging == 'C' {
1141				// Renamed or copied: current entry is new name, next entry is old name
1142				if !paths.IsInfrastructurePath(filename) {
1143					changedSeen[filename] = struct{}{}
1144				}
1145				// The old name follows as the next NUL-separated entry - must always skip it
1146				if i+1 < len(entries) && entries[i+1] != "" {
1147					oldName := entries[i+1]
1148					if staging == 'R' && !paths.IsInfrastructurePath(oldName) {
1149						// For renames, old file is effectively deleted
1150						deletedSeen[oldName] = struct{}{}
1151					}
1152					i++ // Skip the old name entry
1153				}
1154				continue
1155			}
1156	
1157			// Skip .entire directory for non-R/C entries
1158			if paths.IsInfrastructurePath(filename) {
1159				continue
1160			}
1161	
1162			// Handle different status codes
1163			switch {
1164			case staging == 'D' || wtStatus == 'D':
1165				// Deleted file - track separately
1166				deletedSeen[filename] = struct{}{}
1167	
1168			case wtStatus == 'M' || wtStatus == 'A':
1169				// Modified or added in worktree
1170				changedSeen[filename] = struct{}{}
1171	
1172			case staging == '?' && wtStatus == '?':
1173				// Untracked file
1174				changedSeen[filename] = struct{}{}
1175	
1176			case staging == 'A' || staging == 'M':
1177				// Staged add or modify
1178				changedSeen[filename] = struct{}{}
1179	
1180			case staging == 'T' || wtStatus == 'T':
1181				// Type change (e.g., file to symlink)
1182				changedSeen[filename] = struct{}{}
1183	
1184			case staging == 'U' || wtStatus == 'U':
1185				// Unmerged (conflict) - include current file state
1186				changedSeen[filename] = struct{}{}
1187			}
1188		}
1189	
1190		changed := make([]string, 0, len(changedSeen))
1191		for file := range changedSeen {
1192			changed = append(changed, file)
1193		}
1194	
1195		deleted := make([]string, 0, len(deletedSeen))
1196		for file := range deletedSeen {
1197			deleted = append(deleted, file)
1198		}
1199	
1200		return changedFilesResult{Changed: changed, Deleted: deleted}, nil
1201	}
