708	func (s *GitStore) buildTreeWithChanges(
709		ctx context.Context,
710		baseTreeHash plumbing.Hash,
711		modifiedFiles, deletedFiles []string,
712		metadataDir, metadataDirAbs string,
713	) (plumbing.Hash, error) {
714		// Get worktree root for resolving file paths
715		// This is critical because fileExists() and createBlobFromFile() use os.Stat()
716		// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
717		// so we must resolve them against repo root, not CWD.
718		repoRoot, err := paths.WorktreeRoot(ctx)
719		if err != nil {
720			return plumbing.ZeroHash, fmt.Errorf("failed to get worktree root: %w", err)
721		}
722	
723		// Build list of tree changes
724		changes := make([]TreeChange, 0, len(modifiedFiles)+len(deletedFiles))
725	
726		// Deleted files → nil Entry means deletion
727		for _, file := range deletedFiles {
728			changes = append(changes, TreeChange{Path: file, Entry: nil})
729		}
730	
731		// Modified/new files → create blobs from disk
732		for _, file := range modifiedFiles {
733			absPath := filepath.Join(repoRoot, file)
734			if !fileExists(absPath) {
735				// File disappeared since detection — treat as deletion
736				changes = append(changes, TreeChange{Path: file, Entry: nil})
737				continue
738			}
739	
740			blobHash, mode, blobErr := createBlobFromFile(s.repo, absPath)
741			if blobErr != nil {
742				// Skip files that can't be staged (may have been deleted since detection)
743				continue
744			}
745	
746			changes = append(changes, TreeChange{
747				Path: file,
748				Entry: &object.TreeEntry{
749					Mode: mode,
750					Hash: blobHash,
751				},
752			})
753		}
754	
755		// Metadata directory files
756		if metadataDir != "" && metadataDirAbs != "" {
757			metaChanges, metaErr := addDirectoryToChanges(s.repo, metadataDirAbs, metadataDir)
758			if metaErr != nil {
759				return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", metaErr)
760			}
761			changes = append(changes, metaChanges...)
762		}
763	
764		return ApplyTreeChanges(s.repo, baseTreeHash, changes)
765	}
