775	// FlattenTree recursively flattens a tree into a map of full paths to entries.
776	func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
777		for _, entry := range tree.Entries {
778			fullPath := entry.Name
779			if prefix != "" {
780				fullPath = prefix + "/" + entry.Name
781			}
782	
783			if entry.Mode == filemode.Dir {
784				// Recurse into subtree
785				subtree, err := repo.TreeObject(entry.Hash)
786				if err != nil {
787					return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
788				}
789				if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
790					return err
791				}
792			} else {
793				entries[fullPath] = object.TreeEntry{
794					Name: fullPath,
795					Mode: entry.Mode,
796					Hash: entry.Hash,
797				}
798			}
799		}
800		return nil
801	}
